// SUPABASE — conexión a la vista episodes_full (programa principal).
// La anon key es pública por diseño: solo permite lectura, gracias a
// las políticas RLS ya configuradas en el proyecto.
// =====================================================================
const SUPABASE_URL = "https://pussrqveblbukhjmqbom.supabase.co";
const SUPABASE_ANON_KEY = "sb_publishable_8PwRXAo2-1taRJHGxYX6TQ_fOP56LnB";

// Convierte una fila de la vista episodes_full (nombres de columnas de
// Supabase) a la misma forma que antes tenía cada objeto del array
// EPISODES embebido, para no tener que tocar el resto del componente.
function mapSupabaseEpisode(row) {
  return {
    episode_number: row.episode_number,
    season_number: row.season_number,
    title: row.title,
    description: row.description,
    publish_date: row.publish_date,
    duration_seconds: row.duration_seconds,
    audio_url: row.audio_url,
    audio_url_spotify: row.audio_url_spotify,
    cover_url: row.cover_image_url,
    is_special: row.is_special,
    participants: row.participants || [],
    topics: row.topics || [],
    works: (row.works_cited || []).map((w) => ({
      type: w.type,
      title: w.title,
      author: w.author,
      year: w.year,
      url: w.url,
    })),
    videogames: row.videogames || [],
    sections: (row.sections || []).map((s) => ({
      name: s.name,
      notes: s.notes,
      timestamp: s.timestamp_seconds,
    })),
  };
}

async function fetchEpisodesFromSupabase() {
  const url = `${SUPABASE_URL}/rest/v1/episodes_full?select=*`;
  const resp = await fetch(url, {
    headers: {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
    },
  });
  if (!resp.ok) {
    throw new Error(`Error ${resp.status} al consultar Supabase`);
  }
  const rows = await resp.json();
  return rows.map(mapSupabaseEpisode);
}

