// -----------------------------------------------------------------
// Helpers
// -----------------------------------------------------------------
function formatDuration(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  if (h > 0) return `${h}h ${String(m).padStart(2, "0")}min`;
  return `${m}min ${String(s).padStart(2, "0")}s`;
}

function formatDate(iso) {
  const d = new Date(iso + "T00:00:00");
  return d.toLocaleDateString("es-ES", { day: "2-digit", month: "long", year: "numeric" });
}

function formatTimestamp(seconds) {
  if (seconds === null || seconds === undefined || seconds === "") return null;
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  if (h > 0) return `${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  return `${m}:${String(s).padStart(2, "0")}`;
}

function normalize(str) {
  return (str || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

// Construye el índice "entidad -> episodios donde aparece"
function buildIndex(episodes) {
  const index = { persona: new Map(), tema: new Map(), seccion: new Map(), obra: new Map(), videojuego: new Map() };

  const add = (map, key, episodeNumber) => {
    if (!map.has(key)) map.set(key, { name: key, episodes: [] });
    map.get(key).episodes.push(episodeNumber);
  };

  episodes.forEach((ep) => {
    ep.participants.forEach((p) => add(index.persona, p.name, ep.episode_number));
    ep.topics.forEach((t) => add(index.tema, t, ep.episode_number));
    ep.sections.forEach((s) => add(index.seccion, s.name, ep.episode_number));
    ep.works.forEach((w) => add(index.obra, w.title, ep.episode_number));
    (ep.videogames || []).forEach((v) => add(index.videojuego, v.title, ep.episode_number));
  });

  return index;
}

const CATEGORY_META = {
  persona: { label: "Personas", icon: Users },
  tema: { label: "Temas", icon: Tag },
  seccion: { label: "Secciones", icon: Radio },
  obra: { label: "Obras citadas", icon: BookOpen },
  videojuego: { label: "Videojuegos", icon: Gamepad2 },
};

function highlight(text, query) {
  if (!query) return text;
  const nText = normalize(text);
  const nQuery = normalize(query);
  const idx = nText.indexOf(nQuery);
  if (idx === -1) return text;
  return (
    <>
      {text.slice(0, idx)}
      <mark className="hc-mark">{text.slice(idx, idx + query.length)}</mark>
      {text.slice(idx + query.length)}
    </>
  );
}

// =====================================================================
// Sub-componente: lista de etiquetas con colapso si hay muchas
// =====================================================================
function TagGroup({ label, items, renderItem, keyFn, threshold = WORKS_COLLAPSE_THRESHOLD }) {
  const [expanded, setExpanded] = useState(false);
  if (!items || items.length === 0) return null;
  const visible = expanded ? items : items.slice(0, threshold);
  const hidden = items.length - threshold;

  return (
    <>
      <div className="hc-card-section-label">{label}</div>
      <div className="hc-inline-tags">
        {visible.map((item) => renderItem(item))}
        {!expanded && hidden > 0 && (
          <button className="hc-tag hc-tag-more" onClick={() => setExpanded(true)}>
            +{hidden} más <ChevronDown size={12} style={{ display: "inline", verticalAlign: -2 }} />
          </button>
        )}
      </div>
    </>
  );
}

